        $parentUsersCache = [];

        foreach ($studentsData as $index => $s) {
            $nisnClean = preg_replace('/\D/', '', $s['nisn'] ?: (string) ($index + 1000));
            $parentName = $s['parent_name'] ?: ('Wali '.ucwords(strtolower($s['name'])));
            $emailWali = $s['parent_email'] ?: ('wali_'.$nisnClean.'@parent.test');
            $phoneWali = $s['parent_phone'] ?: ('0812'.substr(str_pad($nisnClean, 8, '0', STR_PAD_LEFT), -8));

            // Hubungkan saudara kandung jika memiliki nomor telepon atau email orang tua yang sama
            $cacheKey = $s['parent_phone'] ?: ($s['parent_email'] ?: $nisnClean);
            if (isset($parentUsersCache[$cacheKey])) {
                $parentProfile = $parentUsersCache[$cacheKey];
            } else {
                $userParent = User::firstOrCreate([
                    'phone' => $phoneWali,
                ], [
                    'name' => $parentName,
                    'email' => $emailWali,
                    'password' => Hash::make('password'),
                    'role' => 'parent',
                ]);

                // Cegah duplikasi email jika no hp sama tapi email seeder berbeda
                if (! $userParent->wasRecentlyCreated && $userParent->email !== $emailWali && User::where('email', $emailWali)->where('id', '!=', $userParent->id)->exists()) {
                    $emailWali = 'wali_'.$userParent->id.'_'.$nisnClean.'@parent.test';
                }

                $parentProfile = ParentProfile::firstOrCreate([
                    'user_id' => $userParent->id,
                ], [
                    'full_name' => $parentName,
                    'phone' => $phoneWali,
                    'contact_email' => $emailWali,
                    'address' => 'Desa Cibuntu, Kec. Cibitung, Kab. Bekasi',
                ]);

                $parentUsersCache[$cacheKey] = $parentProfile;
            }

            // Tanggal lahir realistis
            $birthYear = 2026 - (6 + (int) $s['class']);
            $birthMonth = str_pad((($index * 3) % 12) + 1, 2, '0', STR_PAD_LEFT);
            $birthDay = str_pad((($index * 5) % 28) + 1, 2, '0', STR_PAD_LEFT);
            $birthDate = "{$birthYear}-{$birthMonth}-{$birthDay}";

            // Buat Data Siswa Nyata
            Student::create([
                'parent_id' => $parentProfile->id,
                'nis' => $s['nisn'] ?: null,
                'nism' => $s['nism'] ?? null,
                'full_name' => $s['name'],
                'gender' => $s['gender'],
                'birth_date' => $birthDate,
                'class_level' => $s['class'],
                'rombel' => $s['rombel'],
                'entry_year' => $s['entry_year'],
                'status' => Student::STATUS_ACTIVE,
                'email' => 'siswa_'.$nisnClean.'@pondok.test',
                'phone' => '0813'.substr(str_pad($nisnClean, 8, '0', STR_PAD_LEFT), -8),
